class Solution {
    public int minInsertions(String text){
        int insertions=0,need=0;
        for(char value:text.toCharArray())if(value=='('){
            if(need%2==1){
                insertions++;
                need--;
            }
            need+=2;
        }else{
            need--;
            if(need<0){
                insertions++;
                need=1;
            }
        }
        return insertions+need;
    }
}

